import { CodemodeSandbox, loadQuickJSWasm } from "<installed-root>/node_modules/@super-pi/codemode/dist/index.js";
import wasmPath from "<installed-root>/node_modules/quickjs-wasi/quickjs.wasm" with { type: "file" };
import { benchmarkBunRuntime } from "<repo>/scripts/bench/codemode-bun.ts";
await benchmarkBunRuntime(CodemodeSandbox, loadQuickJSWasm, "./worker.ts", wasmPath, import.meta.url);

reproduction.runnerMjs:
import {execFileSync} from 'node:child_process';
import {copyFileSync,readdirSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const root=fileURLToPath(new URL('.',import.meta.url));
execFileSync('bun',['build','--compile','./entry.ts','./worker.ts','--outfile','./codemode-probe.exe'],{cwd:root,timeout:30000,windowsHide:true,stdio:'inherit'});
copyFileSync(new URL('./codemode-probe.exe',import.meta.url),new URL('./empty/codemode-probe.exe',import.meta.url));
const contents=readdirSync(new URL('./empty/',import.meta.url));
if(contents.length!==1||contents[0]!=='codemode-probe.exe') throw Error('Expected only the executable');
const output=execFileSync(fileURLToPath(new URL('./empty/codemode-probe.exe',import.meta.url)),[],{cwd:fileURLToPath(new URL('./empty/',import.meta.url)),timeout:30000,windowsHide:true,encoding:'utf8'});
const result=JSON.parse(output);
writeFileSync(new URL('./bun-result.json',import.meta.url),JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify(result));
